import * as fs from "node:fs";
import * as fsp from "node:fs/promises";
async function main(): Promise<void> {
  const f: any = fs;
  console.log("access:" + fs.access.length + " " + "appendFile:" + fs.appendFile.length + " " + "chmod:" + fs.chmod.length + " " + "close:" + fs.close.length + " " + "copyFile:" + fs.copyFile.length + " " + "open:" + fs.open.length + " " + "read:" + fs.read.length + " " + "readFile:" + fs.readFile.length + " " + "readFileSync:" + fs.readFileSync.length + " " + "readdir:" + fs.readdir.length + " " + "readdirSync:" + fs.readdirSync.length + " " + "stat:" + fs.stat.length + " " + "statSync:" + fs.statSync.length + " " + "lstat:" + fs.lstat.length + " " + "writeFile:" + fs.writeFile.length + " " + "watch:" + fs.watch.length + " " + "rename:" + fs.rename.length + " " + "mkdtemp:" + fs.mkdtemp.length + " " + "truncate:" + fs.truncate.length + " " + "write:" + fs.write.length + " " + "writev:" + fs.writev.length + " " + "realpathSync:" + fs.realpathSync.length + " " + "symlinkSync:" + fs.symlinkSync.length + " " + "statfsSync:" + fs.statfsSync.length);
  console.log("access:" + fsp.access.length + " " + "chmod:" + fsp.chmod.length + " " + "readFile:" + fsp.readFile.length + " " + "readdir:" + fsp.readdir.length + " " + "stat:" + fsp.stat.length + " " + "lstat:" + fsp.lstat.length + " " + "truncate:" + fsp.truncate.length + " " + "watch:" + fsp.watch.length + " " + "mkdtemp:" + fsp.mkdtemp.length + " " + "symlink:" + fsp.symlink.length + " " + "opendir:" + fsp.opendir.length);
  const s = new f.Stats(1, 33188, 1, 0, 0, 0, 4096, 7, 10, 8, 1000, 2000, 3000, 4000);
  console.log(s.isFile(), s.isDirectory(), s.size, s.mtimeMs, s.mtime.getTime(), Object.keys(s).length);
  const d = new f.Dirent("x", 2, "/tmp");
  console.log(d.name, d.parentPath, d.isDirectory(), d.isFile(), Object.keys(d).join());
  console.log(f._toUnixTimestamp("12"), f._toUnixTimestamp(new Date(5000)), f._toUnixTimestamp.length, f.FileReadStream === f.ReadStream);
  try { await (fsp as any).lchmod("/tmp/x", 0o644); } catch (e: any) { console.log(e.code, e.message); }
}
